//! P6-K meta-tests over the audit tables of `docs/port/audit/` (docs/port/PLAN.md §12.2 P6-K;
//! generated by `uv run python port/oracle/p6k_audit.py --write`).
//!
//! Rust evidence for a Python test is its per-test trace in the tier-1 `tests` corpus
//! (`port/corpus/v1/tier1/tests/**`), which `gcg-diff corpus --tier 1 --require-all` replays
//! through the Rust engine, or a named native Rust test. These tests check that every row of
//! the tables has passing evidence that exists in the repository:
//!
//! - W-56, W-58: every interpretation id has Rust traces, and every gcg-api ruling on one of its
//!   cards is in its review snapshot (a new ruling is printed for re-review and fails);
//! - W-57, W-70: every historical strict xfail and every listed fixed bug has a Rust test;
//! - W-60, W-61, W-62, W-66, W-68: every card whose behaviour these entries pin has a passing
//!   per-test trace or a tagged native test.

use std::collections::{BTreeMap, BTreeSet};

use serde_json::Value;

const ROOT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");
const CORPUS: &str = "port/corpus/v1/tier1/tests";

fn read(rel: &str) -> String {
    std::fs::read_to_string(format!("{ROOT}/{rel}")).unwrap_or_else(|e| panic!("{rel}: {e}"))
}

fn json(rel: &str) -> Value {
    serde_json::from_str(&read(rel)).unwrap_or_else(|e| panic!("{rel}: {e}"))
}

fn s<'a>(v: &'a Value, key: &str) -> &'a str {
    v[key].as_str().unwrap_or("")
}

fn strs(v: &Value) -> Vec<&str> {
    v.as_array()
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default()
}

/// Every per-test trace id of the tier-1 corpus with its recorded outcome.
fn corpus_outcomes() -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    let mut dirs = vec![std::path::PathBuf::from(format!("{ROOT}/{CORPUS}"))];
    while let Some(dir) = dirs.pop() {
        let mut entries: Vec<_> = std::fs::read_dir(&dir)
            .expect("corpus directory")
            .filter_map(Result::ok)
            .map(|e| e.path())
            .collect();
        entries.sort();
        for path in entries {
            if path.is_dir() {
                dirs.push(path);
            } else if path.extension().is_some_and(|x| x == "ndjson") {
                let text = std::fs::read_to_string(&path).expect("readable");
                let mut current: Option<String> = None;
                for line in text.lines() {
                    let rec: Value = serde_json::from_str(line).expect("a record");
                    match s(&rec, "t") {
                        "header" => current = Some(s(&rec, "id").to_owned()),
                        "end" => {
                            if let Some(id) = current.take() {
                                out.insert(id, s(&rec, "outcome").to_owned());
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    out
}

fn base(test_id: &str) -> &str {
    test_id.split('[').next().unwrap_or(test_id)
}

/// `crates/<path>.rs::<fn>`: the file exists and defines the function.
fn native_test_exists(spec: &str) -> bool {
    let Some((path, name)) = spec.split_once("::") else {
        return false;
    };
    std::fs::read_to_string(format!("{ROOT}/{path}"))
        .is_ok_and(|text| text.contains(&format!("fn {name}(")))
}

#[test]
fn w56_every_interpretation_id_has_passing_rust_traces() {
    let outcomes = corpus_outcomes();
    assert!(outcomes.len() > 3000, "{} traces", outcomes.len());
    let doc = json("docs/port/audit/interpretations.json");
    let rows = doc["interpretations"].as_array().expect("interpretations");
    assert_eq!(rows.len(), 27);
    let conflicts: BTreeSet<String> = json("data/conflicts.json")["conflicts"]
        .as_array()
        .expect("conflicts")
        .iter()
        .map(|c| s(c, "id").to_owned())
        .collect();
    for r in rows {
        let id = s(r, "id");
        let traces = strs(&r["rust_traces"]);
        assert!(!traces.is_empty(), "{id}: no Rust trace");
        for t in &traces {
            assert_eq!(
                outcomes.get(*t).map(String::as_str),
                Some("passed"),
                "{id}: {t}"
            );
        }
        let python: BTreeSet<&str> = strs(&r["python_tests"]).into_iter().collect();
        for t in &traces {
            assert!(
                python.contains(base(t)),
                "{id}: {t} is not one of its Python tests"
            );
        }
        for c in strs(&r["conflicts"]) {
            assert!(conflicts.contains(c), "{id}: unknown conflict {c}");
        }
    }
}

#[test]
fn w56_new_rulings_on_interpretation_cards_are_listed_for_re_review() {
    let doc = json("docs/port/audit/interpretations.json");
    let rulings = json("src/gcg_sim/data/gcgapi/rulings.json");
    let mut review = Vec::new();
    for r in doc["interpretations"].as_array().expect("interpretations") {
        let cards: BTreeSet<&str> = strs(&r["tags"]["card"]).into_iter().collect();
        let snapshot: BTreeSet<&str> = strs(&r["review_snapshot"]["rulings"]).into_iter().collect();
        for ruling in rulings.as_array().expect("rulings") {
            let key = format!("{}:{}", s(ruling, "card_number"), s(ruling, "num"));
            if cards.contains(s(ruling, "card_number")) && !snapshot.contains(key.as_str()) {
                review.push(format!("{}: re-review ruling {key}", s(r, "id")));
            }
        }
    }
    assert_eq!(
        review,
        Vec::<String>::new(),
        "rulings to re-review against their interpretation ids"
    );
}

#[test]
fn w57_w70_every_historical_fix_has_a_rust_test() {
    let outcomes = corpus_outcomes();
    let doc = json("docs/port/audit/regressions.json");
    let xfails = doc["xfails"].as_array().expect("xfails");
    assert_eq!(xfails.len(), 90, "89 strict xfail marks on 90 tests");
    let commits: BTreeSet<&str> = xfails.iter().map(|x| s(x, "commit")).collect();
    assert_eq!(
        commits,
        ["0e1d3e8", "0ee591d", "102e72b", "7c47b86", "ddb9f4f"]
            .into_iter()
            .collect()
    );
    let mut missing = Vec::new();
    for x in xfails {
        let traces = strs(&x["rust_traces"]);
        if traces.is_empty()
            || traces
                .iter()
                .any(|t| outcomes.get(*t).map(String::as_str) != Some("passed"))
            || traces.iter().any(|t| base(t) != s(x, "test"))
        {
            missing.push(s(x, "test").to_owned());
        }
    }
    for b in doc["bugs"].as_array().expect("bugs") {
        let traces = strs(&b["rust_traces"]);
        let native = strs(&b["rust_native"]);
        let traced = !traces.is_empty()
            && traces
                .iter()
                .all(|t| outcomes.get(*t).map(String::as_str) == Some("passed"));
        let natives = !native.is_empty() && native.iter().all(|n| native_test_exists(n));
        let not_applicable = !s(b, "not_applicable").is_empty();
        if !(traced || natives || not_applicable) {
            missing.push(format!("bug: {}", s(b, "bug")));
        }
    }
    assert_eq!(missing, Vec::<String>::new(), "fixes without a Rust test");
}

/// The cards whose behaviour W-60, W-61, W-62, W-66 and W-68 pin.
const PINNED_CARDS: [(&str, &[&str]); 5] = [
    ("W-60", &["GD05-089", "ST12-013", "ST14-014"]),
    (
        "W-61",
        &[
            "ST09-004", "GD02-086", "GD05-101", "GD04-100", "T-014", "T-021", "T-022", "T-029",
        ],
    ),
    (
        "W-62",
        &[
            "GD01-122", "GD03-079", "GD03-104", "GD03-109", "GD03-114", "GD03-115", "GD04-039",
            "GD04-087", "GD04-095", "GD04-106", "GD04-108", "GD05-089", "GD05-124", "ST02-016",
            "ST07-009", "ST08-013", "ST12-012", "ST14-014",
        ],
    ),
    (
        "W-66",
        &["GD01-103", "GD02-055", "GD03-116", "GD04-114", "GD05-117"],
    ),
    (
        "W-68",
        &[
            "GD01-004", "ST01-004", "ST01-010", "ST02-014", "ST04-001", "ST04-013", "GD05-072",
            "GD05-083",
        ],
    ),
];

/// `// gcg-tags: ... card=X ...` lines of the native tests in `crates/gcg-engine/tests/`.
fn native_card_tags() -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for entry in std::fs::read_dir(format!("{ROOT}/crates/gcg-engine/tests"))
        .expect("tests directory")
        .filter_map(Result::ok)
    {
        let path = entry.path();
        if path.extension().is_some_and(|x| x == "rs") {
            let text = std::fs::read_to_string(&path).expect("readable");
            for line in text.lines() {
                if let Some(tags) = line.trim().strip_prefix("// gcg-tags:") {
                    for t in tags.split_whitespace() {
                        if let Some(card) = t.strip_prefix("card=") {
                            out.insert(card.to_owned());
                        }
                    }
                }
            }
        }
    }
    out
}

#[test]
fn pinned_cards_have_passing_rust_behaviour_tests() {
    let outcomes = corpus_outcomes();
    let tags = json("port/corpus/v1/tier1/tests/tags.json");
    let mut by_card: BTreeMap<&str, BTreeSet<String>> = BTreeMap::new();
    for t in tags["tags"].as_array().expect("tags") {
        if s(t, "mark") == "card" {
            by_card.entry(s(t, "value")).or_default().insert(format!(
                "{}::{}",
                s(t, "path"),
                s(t, "test")
            ));
        }
    }
    let native = native_card_tags();
    let mut report = Vec::new();
    for (entry, cards) in PINNED_CARDS {
        for card in cards {
            let tests = by_card.get(card).cloned().unwrap_or_default();
            let traced = outcomes
                .iter()
                .filter(|(id, outcome)| tests.contains(base(id)) && outcome.as_str() == "passed")
                .count();
            if traced == 0 && !native.contains(*card) {
                report.push(format!(
                    "{entry} {card}: no passing trace and no native test"
                ));
            }
        }
    }
    assert_eq!(report, Vec::<String>::new());
    for card in [
        "GD05-089", "ST12-013", "ST14-014", "GD01-103", "GD02-055", "GD01-004",
    ] {
        assert!(native.contains(card), "{card}: native P6-K test");
    }
}
